import java.util.Scanner;

public class Main {
    static long[] sequence = new long[30];

    static long process(long n) {
        if (n <= 6) return n;
        long best = (long) 1e9;
        long alternative = (long) 1e9;
        for (int i = 0; i < 20; i++) {
            if (sequence[i] > n) {
                best = process(n % sequence[i - 1]) + i * (n / sequence[i - 1]);
                break;
            }
        }
        for (int i = 0; i < 20; i++) {
            if (sequence[i] >= n) {
                if (sequence[i] - n >= n) best = (long) 1e9;
                else alternative = process(sequence[i] - n) + (i + 1);
                break;
            }
        }
        return Math.min(best, alternative);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        sequence[0] = 1;
        for (int i = 1; i < 18; i++) {
            sequence[i] = sequence[i - 1] * 10 + 1;
        }
        long num = scanner.nextLong();
        System.out.println(process(num));
        scanner.close();
    }
}
